async function deliverEmail(deps, orderId, kind, key, extra = {}) {
  try {
    const order = await loadOrder(deps.db, orderId);
    if (!order?.email) return "no_email";
    const claim = await deps.db.rpc("shop_email_claim", { p_order: orderId, p_kind: kind, p_key: key, p_to: order.email });
    if (claim == null) return "duplicate";
    if (!deps.mailer.configured) {
      await deps.db.rpc("shop_email_result", { p_id: claim, p_status: "skipped", p_provider_id: null, p_error: "Email provider not configured" });
      return "skipped";
    }
    try {
      const { id } = await deps.mailer.send(order.email, renderEmail(kind, order, { siteUrl: deps.siteUrl, replyTo: deps.replyTo, ...extra }));
      await deps.db.rpc("shop_email_result", { p_id: claim, p_status: "sent", p_provider_id: id, p_error: null });
      return "sent";
    } catch (err) {
      await deps.db.rpc("shop_email_result", { p_id: claim, p_status: "failed", p_provider_id: null, p_error: err.message });
      return "failed";
    }
  } catch (err) {
    console.error("email", kind, orderId, err);
    return "failed";
  }
}

