  const user = await res.json();
  if (!user.id || !UUID.test(user.id)) throw new HttpError(401, "unauthorized");
  const ok = await deps.db.rpc("shop_is_admin_user", { p_user: user.id });
  if (!ok) throw new HttpError(403, "forbidden");
